import { Component, h, Prop, Element, Host, ComponentInterface } from '@stencil/core';
import classnames from 'classnames';
import { Slot, Slots } from '@src/framework/decorators';
import { CardSize } from './card';

const prefix = 'ks-card';

/**
 * @slot default - The slot for the card body content rendered beneath the header.
 * @slot title - The slot for the card's title section. Overrides the `title` prop if provided.
 * @slot titleSuffix - The slot for custom suffix content next to the title. Overrides the `titleSuffix` prop if provided.
 * @slot headerExtra - The slot for headerExtra content in the card's header, usually on the right.
 * @part base - The base container of the component.
 * @part header - The header section containing title and headerExtra content.
 * @part title - The title container in the header.
 * @part body - The body section containing the default slot content.
 * @part titleSuffix - The title suffix section next to the title.
 */
@Component({
  tag: 'ks-card',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCard implements ComponentInterface {
  @Element() el!: HTMLKsCardElement;

  /** The size of the card. Can be one of the following values: `"md"` or `"sm"`. */
  @Prop() size: CardSize = 'md';
  /** The title of the card, which is displayed prominently at the top. */
  @Prop() title = '';
  /** Optional suffix to be displayed next to the card title, providing additional information or context. */
  @Prop() titleSuffix?: string;

  @Slot({ slotname: 'headerExtra' }) private headerExtraSlot?: Slots;
  @Slot({ slotname: 'title' }) private titleSlot?: Slots;
  @Slot({ slotname: 'titleSuffix' }) private titleSuffixSlot?: Slots;
  @Slot({ slotname: '_default' }) private defaultSlot?: Slots;

  render() {
    const cls = classnames(prefix, `${prefix}--${this.size}`);
    return (
      <Host class="KsCard">
        <div class={cls} part="base">
          {(this.headerExtraSlot || this.title || this.titleSlot) && (
            <div class={classnames(`${prefix}__head`, `${prefix}__head--${this.size}`)} part="header">
              <div class={`${prefix}__head-title`} part="title">
                <slot name="title">{this.title}</slot>
                {(this.titleSuffix || this.titleSuffixSlot) && (
                  <span class={`${prefix}__head-titleSuffix`} part="titleSuffix">
                    <slot name="titleSuffix">{this.titleSuffix}</slot>
                  </span>
                )}
              </div>
              <slot name="headerExtra"></slot>
            </div>
          )}
          {this.defaultSlot && (
            <div class={`${prefix}__body`} part="body">
              <slot></slot>
            </div>
          )}
        </div>
      </Host>
    );
  }
}
